import React, { useState } from 'react'
import Accordion from '@mui/material/Accordion';
import AccordionSummary from '@mui/material/AccordionSummary';
import AccordionDetails from '@mui/material/AccordionDetails';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
// import ImageComponent from "@/app/components/ImageComponent";
// import { handleImageError } from "@/services/utils/utils";
import { Skeleton } from "@mui/material";
import { BASE_URL } from 'src/utils/config';
import { handleImageError } from 'src/utils/urlUtilis';
import styles from "./page.module.scss";
import { axios } from '../../utils/axios';

function AccordionItem({data,privilegesItems, setPrivilegesItems, onChange, value}) {
    const [expanded, setExpanded] = useState(false);
    const [loading, setLoading] = useState(false);

    const getamenityapi = async (url) => {
        const resp = await axios.get(url);
        if (resp.status === 200) {
          if (resp.data?.data?.privilegeItemList) {
            setPrivilegesItems((prev)=>({...prev,
              [data._id]: resp.data.data.privilegeItemList}));
          }
        }
      };

    const handleChange = async (_, isExpanded) => {
        setExpanded(isExpanded);
        if (isExpanded && !privilegesItems[data._id]) {
            setLoading(true);
            try {
                const url = `module/listing/privilegesItems?privilegeId=${data._id}`;
              await getamenityapi(url); // Fetch 
            } catch (error) {
              console.error("Error fetching amenities:", error);
            } finally {
              setLoading(false);
            }
          }
    }

  return (
    <Accordion  expanded={expanded} onChange={handleChange}>
            <AccordionSummary
          expandIcon={<ExpandMoreIcon />}
          aria-controls="panel1-content"
          id="panel1-header"
        >
          {data.name}
        </AccordionSummary>
        <AccordionDetails>
        <div className={`${styles.regional_images}`}>
      {loading? Array.from({ length: 3 }).map(()=>(<Skeleton sx={{height: '150px'}}/>)):Array.isArray(privilegesItems[data._id]) && privilegesItems[data._id].length>0 ? privilegesItems[data._id].map((item)=>(
                  <div className="d-flex flex-column" key={`region${item._id}`}>
                    <label htmlFor={`check${item._id}`}>
                      <input
                        hidden
                        type="checkbox"
                        name="checkoffer"
                        id={`check${item._id}`}
                        value={item._id}
                        onClick={onChange}
                        checked={value.includes(item._id)}
                      />

                      <div className={`${styles.labelcheck}`}>
                        <div className={`${styles.icon}`}>
                          <img
                            src={BASE_URL + item.icon}
                            width={45}
                            height={45}
                            alt=""
                            onError={handleImageError}
                          />
                        </div>

                        <p className={`${styles.para} m-0`}>{item.name}</p>
                      </div>
                    </label>
                  </div>
                )): 'No Data Found' }
          </div>
        </AccordionDetails>
          </Accordion>
  )
}

export default AccordionItem
